Variable Default Description *host login.eqemulator.net This is the hostname of the loginserver endpoint *port 5998 Loginserver endpoint port legacy 0 When set to 1, will connect to old netcode (IE current public LS) account Account forum username for public EQEmu authentication, this is used with worldserver registration password Account forum password <p>Warning</p> <p>Your server will need to use port 5998 to communicate with the public EQEmu loginserver. Do NOT change that value as you would for your eqhost file, based on client.</p> <p>Note</p> <p>Multiple Loginserver endpoints can be established by using the same configuration above, however declaring your loginserver subsections with a number, below is an example</p> <pre><code>{
  "world": {
    "loginserver1": {
      "account": "",
      "host": "login.eqemulator.net",
      "legacy": "1",
      "password": "",
      "port": "5998"
    },
    "loginserver2": {
      "account": "",
      "host": "myloginserver.net",
      "password": "",
      "port": "5998"
    }
  }
}
</code></pre>

PerlLua <pre><code>sub EVENT_DISCOVER_ITEM {
    #:: Create a scalar variable to store the item link
    $discovereditem = quest::varlink($itemid);
    #:: Shout the discovery to all zones
    quest::shout2("$name has discovered $discovereditem!  Yay!");
}
</code></pre> <pre><code>function event_discover_item(e)    
    --:: Create a scalar variable to store the item link
    local item_link = eq.item_link(e.item:GetID());
    --:: Emote the discovery to all zones
    eq.world_emote(335, "$name has discovered " .. item_link .. "!  Yay!");
end
</code></pre>

PerlLua <pre><code>sub EVENT_SPAWN {
    #:: Create a proximity, 100 units across, 100 units tall, without proximity say
    quest::set_proximity($x - 50, $x + 50, $y - 50, $y + 50, $z - 50, $z + 50, 0);
}

sub EVENT_EXIT {
    #:: Turn pvp off
    quest::pvp("off");
}
</code></pre> <pre><code>function event_spawn(e)
    --:: Create a proximity, 100 units across, 100 units tall, without proximity say
    local x = e.self:GetX();
    local y = e.self:GetY();
    local z = e.self:GetZ();
    eq.set_proximity((x - 50), (x + 50), (y - 50), (y + 50), (z - 50), (z + 50), 0);    
end

function event_exit(e)
    --:: Turn pvp off
    e.other:SetPVP("off");
end
</code></pre>

PerlLua <pre><code>sub EVENT_FEIGN_DEATH {
    #:: See if the player has a pet
    if ($client-&gt;GetPetID()) {
        #:: Identify the pet by ID and kill it
        $pet_entity = $entity_list-&gt;GetMobByID($client-&gt;GetPetID());
        $pet_entity-&gt;Kill();
    }
}
</code></pre> <pre><code>function event_feign_death(e)
    --:: See if the player has a pet
    local pet_id = e.other:GetPet():GetID();
    if (pet_id &gt; 0) then
        --:: Identify the pet by ID and kill it
        local pet_entity = entity_list:GetMob(pet_id);
        pet_entity:Kill();
    end
end
</code></pre>

PerlLua <pre><code>sub EVENT_KILLED_MERIT {
    #:: Get the name of the mob to use in the data bucket
    my $slain = $npc-&gt;GetCleanName();
    #:: Set the quest data bucket--this would apply to all group members
    my $bucket_name = $client-&gt;CharacterID() . "-Slain";
    quest::set_data($bucket_name, 1);
    #:: Display an emote message to each client in yellow to notify them that they received credit
    $client-&gt;Message(15, "You have received credit for killing $slain.");
}
</code></pre> <pre><code>function event_killed_merit(e)
    --:: Get the name of the mob to use in the quest global
    local slain = e.self:GetCleanName();
    --:: Set the quest global--this would apply to all group members
    local bucket_name = e.other:CharacterID() .. "-Slain";
    eq.set_data(bucket_name, 1);
    --:: Display an emote message to each client in yellow to notify them that they received credit
    e.other:Message(15, "You have received credit for killing " .. slain .. ".");    
end
</code></pre>

